import clsx from 'clsx';
import { useEffect, useState } from 'react';
import { useFormContext } from 'react-hook-form';
import { BottomSheet } from '~/shared/ui/bottom-sheets/bottom-sheet';
import { TextInput } from '~/shared/ui/text-input/text-input';
import { BaseSelectList, LabelEvent, SelectOption, SelectProps } from './base';

export const Select = ({
  placeholder,
  name,
  option,
  labels,
  values,
  classStr,
  disabled,
  description,
  isErrorPaddingPresent,
}: SelectProps) => {
  const [isOpenBottomSheet, setIsOpenBottomSheet] = useState(false);

  const handleCloseBottomSheet = () => {
    setIsOpenBottomSheet(false);
    if ((!value || value?.length < 0) && option?.required) {
      setError(name, { type: 'required', message: option?.required.toString() ?? null });
    }
  };

  const { register, setValue, clearErrors, watch, getValues, setError } = useFormContext();
  const value = watch(name);

  const defaultValue = getValues(name);
  const selectedValue = watch(name, defaultValue);
  const selectedLabel = labels[values.indexOf(selectedValue)];

  const onInputClick = (event: React.MouseEvent<HTMLDivElement, MouseEvent>) => {
    event.preventDefault();
    setIsOpenBottomSheet(true);
  };

  const options = values.map((itemValue, index) => ({
    value: itemValue,
    label: labels[index],
  }));

  const onLabelChange = ({ event, option: selectedOption }: { event: LabelEvent; option: SelectOption<string> }) => {
    setValue(name, selectedOption.value);
    setIsOpenBottomSheet(false);
    clearErrors(name);
  };

  useEffect(() => {
    if (value?.length > 0) {
      setValue(name, selectedValue);
    }
  }, []);

  return (
    <div className={clsx('flex flex-col', { 'mb-8': !!description })}>
      <TextInput
        label={placeholder}
        {...register(name)}
        readOnly
        onClick={(e) => !disabled && onInputClick(e)}
        displayLabel={selectedLabel}
        selectMode
        classStr={classStr}
        disabled={!!disabled}
        description={description}
        isErrorPaddingPresent={isErrorPaddingPresent ?? !!!description}
      />
      <BottomSheet title={placeholder} open={isOpenBottomSheet} onClose={handleCloseBottomSheet}>
        <BaseSelectList
          options={options}
          selectedOption={selectedValue ? { value: selectedValue, label: selectedLabel } : undefined}
          onLabelChange={onLabelChange}
        />
      </BottomSheet>
    </div>
  );
};
